    def test_orden_de_variables_y_path(self):
        falso = Falso()
        estrella = self.crear("herramientas/blender")
        s = self.sistema(falso, binarios=("blender",), entorno={"HOME": str(self.carpeta), "STARSEED_BLENDER": estrella})
